xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        W := 0.6;
        N := 5;
        D := W / N;
        WX := D;
        WY := D;
        WZ := D;

        S[0] := '     |     |  1  |     |     ';
        S[1] := '     |  1  | 101 |  1  |     ';
        S[2] := '  1  | 101 |10 01| 101 |  1  ';
        S[3] := '     |  1  | 101 |  1  |     ';
        S[4] := '     |     |  1  |     |     ';

        function GetType(x1, y1, z1);
        begin
            if (x1 < 0) or (y1 < 0) or (z1 < 0) or (x1 >= N) or (y1 >= N) or (z1 >= N) then
                Result := ' '
            else
                Result := copy(S[N-1-z1], (N + 1) * y1 + x1 + 1, 1);
        end;

        procedure CalcCubie(No);
        begin
            x := No mod N;
            y := No div N mod N;
            z := No div N div N;
            for i := 0 to 5 do
                Colors[i] := -1;
            CType := GetType(x,y,z);
            if CType = '1' then begin
                if GetType(x-1,y,z) = ' ' then Colors[0] := clRed;
                if GetType(x+1,y,z) = ' ' then Colors[1] := clOrange;
                if GetType(x,y-1,z) = ' ' then Colors[2] := clBlue;
                if GetType(x,y+1,z) = ' ' then Colors[3] := clGreen;
                if GetType(x,y,z-1) = ' ' then Colors[4] := clYellow;
                if GetType(x,y,z+1) = ' ' then Colors[5] := clWhite;
            end;
            if CType <> ' ' then begin 
                DWX := D * (2 * x - N + 1);
                DWY := D * (2 * y - N + 1);
                DWZ := D * (2 * z - N + 1);
                CCount := 1;
            end else
                CCount := 0;
        end;
